  def icon(name, size: 16, **overrides)
    entry = ICONS[name.to_s]
    paths, custom = entry.is_a?(Hash) ? [entry[:paths], entry.except(:paths)] : [entry, {}]
    attributes = ICON_DEFAULTS.merge(custom, overrides, width: size, height: size)
    content_tag(:svg, paths.to_s.html_safe, attributes)
  end

